{
  "environment": {
    "container_type": "pod",
    "namespace": "hostpath-escape",
    "service_account": "default",
    "os": "Alpine Linux v3.24 (kernel 6.18.58.1-microsoft-standard-WSL2, x86_64)",
    "is_root": true
  },
  "credentials": {
    "has_sa_token": true,
    "token_subject": "system:serviceaccount:hostpath-escape:default"
  },
  "permissions": {
    "source": "selfsubjectrulesreview",
    "resource_rules": [
      {"apiGroups": ["authorization.k8s.io"], "resources": ["selfsubjectaccessreviews", "selfsubjectrulesreviews"], "verbs": ["create"]},
      {"apiGroups": ["authentication.k8s.io"], "resources": ["selfsubjectreviews"], "verbs": ["create"]},
      {"apiGroups": ["certificates.k8s.io"], "resources": ["clustertrustbundles"], "verbs": ["get", "list", "watch"]}
    ]
  },
  "tools": {
    "available": ["wget", "nc", "busybox", "mount", "nsenter", "sh", "cat", "ls"],
    "unavailable": ["curl", "kubectl", "ncat", "socat", "python", "python3", "perl", "ruby", "openssl", "bash", "crictl", "ctr", "docker"]
  },
  "api": {
    "reachable": true,
    "endpoint": "https://10.96.0.1:443"
  }
}
